const FALLBACK: CategoryPack = CATEGORY_PACKS["business"] as CategoryPack;

/** The pack for a category, falling back to the generic business pack. */
export function categoryPack(categorySlug: string): CategoryPack {
  const direct = CATEGORY_PACKS[categorySlug];
  if (direct) return direct;
  // New catalogue categories borrow the closest verified pack.
  const alias = CATALOG_BY_SLUG[categorySlug]?.pack;
  if (alias && CATEGORY_PACKS[alias]) return CATEGORY_PACKS[alias] as CategoryPack;
  return FALLBACK;
}

/** N images from one bucket, rotated by `seed` so sibling demos differ. */
export function bucketImages(
  categorySlug: string,
  bucket: PackBucket,
  count: number,
  seed = 0,
): string[] {
  const pack = categoryPack(categorySlug);
  const pool = pack[bucket]?.length ? pack[bucket] : pack.hero;
  if (!pool.length) return [];
  const out: string[] = [];
  for (let i = 0; i < count; i++) out.push(pool[(Math.abs(seed) + i) % pool.length] as string);
  return out;
}

/** Flat mixed list (hero → gallery → service → product → team). */
export function packImages(categorySlug: string, count: number, seed = 0): string[] {
  const pack = categoryPack(categorySlug);
  const flat = BUCKETS.flatMap((b) => pack[b] ?? []);
  if (!flat.length) return [];
  const out: string[] = [];
  for (let i = 0; i < count; i++) out.push(flat[(Math.abs(seed) + i) % flat.length] as string);
  return out;
}

export function packCategories(): string[] {
  return Object.keys(CATEGORY_PACKS);
}
